cat > /tmp/jwtcheck.test.ts <<'EOF'
import { test, expect } from "vitest";
import { createHmac } from "node:crypto";
import { verifyToken } from "/tmp/token-saver-runs/red-K1-jwt-deadline-5/src/auth/jwt.ts";
const b = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (h: object, p: object, s = "k") => { const d = `${b(h)}.${b(p)}`; return `${d}.${createHmac("sha256", s).update(d).digest("base64url")}`; };
const now = Math.floor(Date.now()/1000);
test("valid", () => expect(verifyToken(sign({alg:"HS256"},{sub:"u",exp:now+60}),"k").sub).toBe("u"));
test("expired", () => expect(() => verifyToken(sign({alg:"HS256"},{sub:"u",exp:now-1}),"k")).toThrow("expired"));
test("wrong secret", () => expect(() => verifyToken(sign({alg:"HS256"},{sub:"u",exp:now+60},"x"),"k")).toThrow("signature"));
test("alg none", () => expect(() => verifyToken(`${b({alg:"none"})}.${b({sub:"u",exp:now+60})}.`,"k")).toThrow("alg"));
test("tampered payload", () => { const t = sign({alg:"HS256"},{sub:"u",exp:now+60}).split("."); t[1]=b({sub:"admin",exp:now+60}); expect(() => verifyToken(t.join("."),"k")).toThrow("signature"); });
test("missing exp", () => expect(() => verifyToken(sign({alg:"HS256"},{sub:"u"}),"k")).toThrow("claims"));
EOF
npx vitest run /tmp/jwtcheck.test.ts --root / 2>&1 | tail -8; npx tsc --noEmit -p . 2>&1 | tail -5; rm /tmp/jwtcheck.test.ts

